let frTeachingTopicsB: [(id: Int, title: String, intro: String, example: String)] = [
    (19, "Sujet et Prédicat", "Chaque phrase anglaise a un sujet (de quoi parle la phrase) et un prédicat (ce que fait le sujet).", "Dans 'The dog runs fast', 'The dog' est le sujet et 'runs fast' est le prédicat."),
    (20, "Le Langage Figuré", "Le langage figuré utilise des images et des comparaisons pour enrichir l'écriture en anglais.", "Dans 'Her smile is sunshine', on compare un sourire au soleil  -  c'est une métaphore."),
    (21, "Le Vocabulaire en Contexte", "On peut deviner le sens d'un mot inconnu grâce aux mots qui l'entourent dans la phrase.", "Dans 'She was famished  -  she hadn't eaten all day', 'famished' veut dire très faim."),
    (22, "L'Idée Principale", "L'idée principale est le message central d'un paragraphe. Les détails de soutien l'appuient.", "Dans un paragraphe sur les lions, l'idée principale peut être: 'Lions are powerful predators.'"),
    (23, "Le Point de Vue", "Le point de vue indique qui raconte l'histoire: première, deuxième ou troisième personne.", "À la première personne on utilise 'I/me', à la troisième 'he/she/they'."),
    (24, "Les Structures Textuelles", "Un texte peut être organisé selon différentes structures: comparaison, cause/effet, problème/solution, séquence.", "Un texte 'cause/effect' explique pourquoi quelque chose arrive et ce qui en résulte."),
    (25, "L'Écriture Narrative", "Un récit a un début, un milieu et une fin. Les dialogues sont ponctués avec des guillemets en anglais.", "Dans une histoire: introduction → problème → climax → résolution."),
    (26, "La Poésie Anglaise", "La poésie utilise des rimes, des strophes, l'allitération et l'assonance pour créer des effets musicaux.", "ABAB signifie que la 1re et 3e ligne riment, et la 2e et 4e ligne riment."),
    (27, "Les Phrases Complexes", "Les conjonctions de coordination FANBOYS (for, and, nor, but, or, yet, so) relient des propositions.", "Dans 'I wanted to go, but it rained', 'but' relie deux propositions indépendantes."),
    (28, "La Voix Active et Passive", "À la voix active, le sujet fait l'action. À la voix passive, le sujet reçoit l'action.", "Actif: 'The dog bit the man.' Passif: 'The man was bitten by the dog.'"),
    (29, "L'Écriture Persuasive", "L'écriture persuasive utilise une thèse, des preuves et des appels à l'émotion (pathos) ou à la raison (logos).", "Un texte persuasif commence par une prise de position claire appelée 'thesis statement'."),
    (30, "Les Figures de Style", "La littérature anglaise utilise des procédés comme le suspense (foreshadowing), l'ironie, le symbolisme et les thèmes.", "Un symbole est un objet qui représente une idée abstraite, comme une colombe pour la paix."),
    (31, "Le But de l'Auteur", "Un auteur peut vouloir informer, persuader ou divertir. Il peut aussi avoir un biais dans son écriture.", "Un article de journal cherche à informer; une publicité cherche à persuader."),
    (32, "La Recherche et les Citations", "Pour citer des sources, on peut paraphraser ou citer directement. Il faut éviter le plagiat.", "En format MLA, on écrit: Auteur, Titre, Date. Les citations directes utilisent des guillemets."),
    (33, "Shakespeare et la Littérature Classique", "Shakespeare a écrit des sonnets, des tragédies et des comédies en pentamètre iambique.", "Un sonnet shakespearien a 14 vers en pentamètre iambique avec le schéma de rimes ABAB CDCD EFEF GG."),
    (34, "L'Étymologie", "Connaître les racines latines et grecques aide à comprendre des mots anglais nouveaux.", "La racine 'bio' (vie) se retrouve dans 'biology', 'biography', 'biodiversity'."),
    (35, "La Grammaire Avancée", "Les signes de ponctuation avancés incluent le point-virgule, le deux-points et le tiret cadratin.", "Le point-virgule relie deux propositions indépendantes liées: 'I studied; I passed.'")
]

